import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as E,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"等离子体基础","description":"","frontmatter":{"title":"等离子体基础","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/plasma-basics.md","filePath":"litho/plasma-basics.md","lastUpdated":1789023840000}'),h={name:"litho/plasma-basics.md"};function d(c,a,m,u,B,b){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="等离子体基础" tabindex="-1">等离子体基础 <a class="header-anchor" href="#等离子体基础" aria-label="Permalink to &quot;等离子体基础&quot;">​</a></h1><div class="epigraph"><p>胶浮雕只是有机掩模。把它变成介质槽和硅边的，是低气压放电里的离子与自由基，不是再一次投影光学。</p><footer>—— 对照 Lieberman–Lichtenberg 等离子体放电基础；Coburn–Winters 表面协同</footer></div><p><a href="/litho/metal-via-co-optimization">上一课</a>把金属–via 收成联立规则。缺口是转印：enclosure 的 AEI 值从腔体来，而仿真门的刻蚀核只是它的紧凑投影。本课起「集成、控制与良率」，钉等离子体基础。<a href="/litho/rie-pattern-transfer">RIE 转印</a> 已写协同图像；这里补放电侧：物种、鞘层、偏置，供后课写选择比与钝化。选择比与 ARDE，留给[下一课](/litho/selectivity-arde）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>电容耦合（CCP）与电感耦合（ICP）在产线共存：前者离子能量与密度耦得紧，后者可相对分开控密度与衬底偏置。鞘层把离子加速向晶圆，中性自由基靠扩散到达。图形化关心的不是等离子体物理全集，而是：到达开口的离子角分布、能量、以及中性通量——它们决定各向异性、损伤和速率。</p><p>缺口是<strong>把腔体读成转印边界条件</strong>，不是从麦克斯韦重讲电磁波。把「等离子体」当黑盒刻蚀按钮，APC 只能拧时间，无法理解为何换功率 CD 就走。</p><h3 id="胶是消耗品电极" tabindex="-1">胶是消耗品电极 <a class="header-anchor" href="#胶是消耗品电极" aria-label="Permalink to &quot;胶是消耗品电极&quot;">​</a></h3><p>抗蚀剂同时是掩模和反应物：它被离子溅射、被氧/氟化学吃，产物进气相改变等离子体。薄胶使这层消耗成为 CD 预算。硬掩模课会把深度预算拆走；本课先承认放电「看见」的是胶与开口，不是版图。</p><p><span class="marginnote">偏置功率大致控离子能量，源功率控密度。拧错旋钮，损伤与选择比一起动。食谱是这对旋钮的合同，不是单一 RF 数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程量：源/偏置功率、气压、气体（Ar、C<sub>x</sub>F<sub>y</sub>、Cl/HBr、O<sub>2</sub> 等按层）、衬底温度。诊断（实验室）：Langmuir、OES、离子能量分析；产线更多靠 OES 与速率监控。与紧凑核的接口：核的密度项对应中性消耗与局部通量，短程项对应侧壁与角分布——校准仍用成对 ADI/AEI，本课只提供物理对应物。</p><p>EUV 薄胶使等离子体窗口更窄：能用来「修」CD 的过刻更少。</p><p>食谱窗口用代表开口矩阵而不是空白片：同一 RF，密线和孤立槽的离子角与中性消耗已经不同。Lieberman–Lichtenberg 给出放电语言；产线用 OES 和速率监控把语言接到每天的腔体，而不是每班重做 Langmuir。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>鞘层电压把离子准直到法向，气压升高碰撞增多、角变宽，各向异性下降。自由基不认方向，提供各向同性化学。Coburn–Winters 协同：离子协助表面反应，使侧壁（少离子）与底部（多离子）速率差出来。聚合物源气体在侧壁沉积，下一课钝化会展开；此处只把放电写成「离子 + 中性 + 沉积前体」三通量。</p>',15)),(e(),n(A,null,{default:r(()=>[p(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E5%8A%9F%E7%8E%87%20%2F%20%E6%B0%94%E4%BD%93%22%5D%20--%3E%20PL%5B%22%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%E5%AF%86%E5%BA%A6%22%5D%0A%20%20BIAS%5B%22%E8%A1%AC%E5%BA%95%E5%81%8F%E7%BD%AE%22%5D%20--%3E%20ION%5B%22%E7%A6%BB%E5%AD%90%E8%83%BD%E9%87%8F%E4%B8%8E%E8%A7%92%22%5D%0A%20%20PL%20--%3E%20RAD%5B%22%E4%B8%AD%E6%80%A7%E8%87%AA%E7%94%B1%E5%9F%BA%E9%80%9A%E9%87%8F%22%5D%0A%20%20ION%20--%3E%20SURF%5B%22%E5%BC%80%E5%8F%A3%E5%BA%95%20%2F%20%E4%BE%A7%E5%A3%81%22%5D%0A%20%20RAD%20--%3E%20SURF%0A%20%20SURF%20--%3E%20AEI%5B%22AEI%20%E8%BE%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写光学成像，不进入 LOB。不把某腔体未公开的速率表当自然常数。等离子体不稳定、打火、颗粒是良率项，后课缺陷再收。</p><p>后课默认：转印边界条件是离子角/能量与中性通量。下一课用它们定义选择比，并与已有 ARDE 课对接而不重写深宽比几何。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图形化等离子体提供定向离子与各向同性自由基，鞘层决定角与能量。</li><li>源/偏置分控是食谱合同；胶同时是掩模和反应物。</li><li>紧凑刻蚀核是这些通量在边上的投影。</li><li>出处：Lieberman &amp; Lichtenberg；Coburn–Winters；RIE 产线通称。</li></ul>',5))])}const f=o(h,[["render",d]]);export{D as __pageData,f as default};
